using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Windows.Forms;using System.Drawing;
internal sealed partial class ControlWindow {
 readonly Button usePreviewCover=new SoftButton();readonly Label previewCoverWhy=new Label();readonly ToolTip previewCoverTips=new ToolTip{ShowAlways=true};ImportOperation captureOperation;Task captureTask;bool capturingCover,previewCoverRequested;string previewCoverResult,previewCoverResultRun;
 void UpdatePreviewCoverButton(){((SoftButton)usePreviewCover).Busy=capturingCover;if(closing){usePreviewCover.Enabled=false;return;}PreviewFrameTarget target;string why;bool ok=TryPreviewTarget(out target,out why);if(capturingCover){ok=false;why="正在保存，请稍候";}else if(ok&&PreviewCovers.HasIndependentCover(library.Doc.Items.First(x=>x.Id==target.CatalogId))){ok=false;why="已有独立封面，不自动覆盖";}else if(ok)why=PreviewCovers.Resolve(target.ResourceSha256)==null?"保存当前预览，不随所选卡片改变":"已有预览截图，再点可替换";else if(State=="starting"||State=="engine-started")why="预览正在准备，稍后可保存";else why=RuntimePresentation.CoverUnavailable(State,why);usePreviewCover.Enabled=ok;previewCoverWhy.Text=why;usePreviewCover.AccessibleDescription=why;previewCoverTips.SetToolTip(usePreviewCover,why);previewCoverTips.SetToolTip(selectedImage,selected!=null&&!PreviewCovers.HasIndependentCover(selected)&&PreviewCovers.ForItem(selected)!=null?"封面来源：预览截图（用户生成识别图）":"原有封面或暂无可靠图片");}
 async Task SavePreviewCover(){if(capturingCover)return;PreviewFrameTarget target;string why;if(!TryPreviewTarget(out target,out why)){libraryHint.Text=RuntimePresentation.CoverUnavailable(State,why);UpdatePreviewCoverButton();return;}var item=library.Doc.Items.First(x=>x.Id==target.CatalogId);if(PreviewCovers.HasIndependentCover(item)){libraryHint.Text="这张正在预览的壁纸已有独立封面，未覆盖。";return;}bool replace=PreviewCovers.Resolve(target.ResourceSha256)!=null;if(replace&&MessageBox.Show(this,"这张壁纸已有一张预览截图，是否用当前画面替换？\n只替换本软件生成的识别图，不修改播放确认。","替换预览截图",MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;capturingCover=true;previewCoverResult=null;previewCoverResultRun=target.Run;UpdatePreviewCoverButton();captureTask=CaptureAndSave(target,replace);await captureTask;}
 async Task CaptureAndSave(PreviewFrameTarget target,bool replace){ImportOperation op=null;try{
   if(!SamePreview(target))throw new OperationCanceledException("预览已改变，未保存识别图");previewCoverTips.Hide(usePreviewCover);PreviewFrame.SetForegroundWindow(new IntPtr(target.Window));await Task.Delay(180);if(!SamePreview(target))throw new OperationCanceledException("预览已改变，未保存识别图");
   captureOperation=op=new ImportOperation(Write);Write("preview-cover-capture-start",new{run=target.Run,resourceSha256=target.ResourceSha256,source="user-preview-screenshot",selectedCatalogId=selected==null?null:selected.Id,loadedCatalogId=target.CatalogId});var result=await op.Run("capture-frame",null,null,0,null,target);var frame=Common.Obj(result["frame"]);var returned=Common.Json.Deserialize<PreviewFrameTarget>(Common.Json.Serialize(frame["target"]));if(Common.Json.Serialize(returned)!=Common.Json.Serialize(target)||Common.S(frame,"image")!="preview.jpg")throw new InvalidDataException("捕获结果不属于本次预览");
   Action guard=()=>{if(closing||op.Cancelled||!SamePreview(target))throw new OperationCanceledException("捕获期间预览已停止或切换，未保存识别图");var current=library.Doc.Items.FirstOrDefault(x=>x.Id==target.CatalogId&&x.RegisteredSha256==target.ResourceSha256);if(current==null||PreviewCovers.HasIndependentCover(current))throw new InvalidOperationException("资源登记或原封面已变化，未覆盖");};
   var binding=PreviewCovers.Publish(Path.Combine(op.Folder,"payload","preview.jpg"),target,Common.S(frame,"imageSha256"),Convert.ToInt32(frame["width"]),Convert.ToInt32(frame["height"]),Common.S(frame,"captureMethod"),"explicit-user-button",replace,guard);
   RefreshCards();if(importDialog!=null&&!importDialog.IsDisposed)importDialog.RefreshPreviewCover(target.ResourceSha256);libraryHint.Text="已为当前预览保存识别图（预览截图）；播放确认未改变。";previewCoverResultRun=target.Run;previewCoverResult="封面已保存，首页卡片已更新；可继续预览。";Write("preview-cover-saved",binding);
  }catch(OperationCanceledException ex){previewCoverResultRun=target.Run;previewCoverResult=ex.Message;if(!closing)libraryHint.Text=ex.Message;Write("preview-cover-cancelled",new{run=target.Run,sha256=target.ResourceSha256,reason=ex.Message});}
   catch(Exception ex){previewCoverResultRun=target.Run;previewCoverResult="封面未保存："+ex.Message;if(!closing){libraryHint.Text="识别图未保存："+ex.Message;libraryHint.ForeColor=Color.Firebrick;}Write("preview-cover-failed",new{run=target.Run,sha256=target.ResourceSha256,reason=ex.Message,previousCoverPreserved=true});}
   finally{if(captureOperation==op)captureOperation=null;if(op!=null)try{LocalImport.CleanPayload(op.Folder);}catch(Exception ex){Write("preview-cover-cleanup-unconfirmed",new{reason=ex.Message});}capturingCover=false;if(!closing&&!IsDisposed)UpdatePreviewCoverButton();}
 }
 async Task StopPreviewCoverCapture(){if(captureOperation!=null&&captureOperation.Busy)captureOperation.Cancel();var task=captureTask;if(task!=null)await task;}
 bool TryPreviewTarget(out PreviewFrameTarget target,out string reason,bool allowStarting=false){target=null;reason="请先打开本软件的窗口预览";
  if(closing||transition||!(activeRunReady||allowStarting)||PlayerRole!="alive"||WorkerRole!="alive"||CurrentRun==null||player==null||activeRunRequest==null)return false;
  try{if(Common.S(activeRunRequest,"mode")!="preview"||player.Run!=CurrentRun||player.Token!=runToken||runJob==null||!runJob.Contains(player.Handle))throw new InvalidDataException("当前不是身份有效的自有窗口预览");ProcessProof.Verify(player.Handle,player.Pid,player.Creation,player.Image);
   string hash=Common.S(activeRunRequest,"expectedSha256"),id=Common.S(activeRunRequest,"selectedCatalogId");if(!PackageAnalysis.HashText(hash)||!library.Doc.Items.Any(x=>x.Id==id&&x.RegisteredSha256==hash))throw new InvalidDataException("本次实际加载资源没有对应的完整哈希登记");
   var load=Common.Read(Path.Combine(CurrentRun,"load-input.json"));var identity=Common.Read(Path.Combine(CurrentRun,"identity.json"));if(Common.S(load,"sourceSha256")!=hash||Common.S(load,"runtimeSha256")!=hash||Common.S(identity,"runtimeSha256")!=hash||Convert.ToInt32(identity["pid"])!=player.Pid)throw new InvalidDataException("本次加载身份记录不一致");
   string first;using(var stream=new FileStream(Path.Combine(CurrentRun,"host.jsonl"),FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(stream)){first=reader.ReadLine();}if(first==null||first.Length>65536)throw new InvalidDataException("缺少预览窗口依据");var report=Common.Json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(first);if(Common.S(report,"phase")!="host")throw new InvalidDataException("缺少自有渲染窗口记录");var data=Common.Obj(report["data"]);var top=Common.Obj(data["window"]);var render=Common.Obj(data["render"]);
   var t=new PreviewFrameTarget{Run=CurrentRun,Token=runToken,ResourceSha256=hash,RuntimeCwp=Common.S(load,"runtimeCwp"),CatalogId=id,PlayerPid=player.Pid,PlayerCreation=player.Creation,PlayerImage=player.Image,Window=Convert.ToInt64(top["hwnd"]),Render=Convert.ToInt64(render["hwnd"])};PreviewFrame.Windows(t);target=t;reason=null;return true;
  }catch(Exception ex){reason=ex.Message;return false;}}
 bool SamePreview(PreviewFrameTarget original){PreviewFrameTarget now;string reason;return TryPreviewTarget(out now,out reason)&&now.Run==original.Run&&now.Token==original.Token&&now.ResourceSha256==original.ResourceSha256&&now.PlayerPid==original.PlayerPid&&now.PlayerCreation==original.PlayerCreation&&now.Render==original.Render&&now.Window==original.Window;}
}
